/**
 * Smart Search configuration, shared by the browser worker and the build-time embeddings
 * script so that both produce comparable vectors.
 *
 * all-MiniLM-L6-v2 was chosen after comparing four small (23–34 MB) embedding models on paraphrase
 * queries against the atlas documents (see docs/ARCHITECTURE.md).
 */
export const SMART_SEARCH_MODEL = {
  id: 'Xenova/all-MiniLM-L6-v2',
  dtype: 'q8',
  pooling: 'mean',
  dimensions: 384,
} as const

/** Precomputed document embeddings, generated by `npm run data:embeddings`. */
export const EMBEDDINGS_MANIFEST_URL = '/search/embeddings.json'
export const EMBEDDINGS_VECTORS_URL = '/search/embeddings.bin'

export interface EmbeddingsManifest {
  model: string
  dtype: string
  dimensions: number
  /** Hash of the embedded texts; must match the documents the app builds at runtime. */
  contentHash: string
  /** Document ids, in the order of the vectors. */
  ids: string[]
  /** Vectors are stored as int8 (value × 127) after L2 normalization. */
  quantization: 'int8'
}
